package com.bank.spark.service;

import com.bank.spark.model.TaskStat;
import java.util.List;
import java.util.logging.Logger;

// Flags stragglers and decides whether a speculative copy is worthwhile.
public class SpeculationAdvisor {

    private static final Logger log = Logger.getLogger(SpeculationAdvisor.class.getName());

    private final double multiplier;
    private final double skewInputRatio;

    public SpeculationAdvisor(double multiplier, double skewInputRatio) {
        this.multiplier = multiplier;
        this.skewInputRatio = skewInputRatio;
    }

    public void evaluate(List<TaskStat> tasks) {
        long medianDuration = median(tasks.stream().mapToLong(TaskStat::getDurationMs).sorted().toArray());
        long medianInput = median(tasks.stream().mapToLong(TaskStat::getInputMb).sorted().toArray());

        for (TaskStat t : tasks) {
            boolean straggler = t.getDurationMs() > multiplier * medianDuration;
            if (!straggler) continue;

            // Environmental straggler: similar input but slow → speculation helps.
            if (t.getInputMb() <= skewInputRatio * medianInput) {
                log.info(() -> "Task " + t.getTaskId() + " straggler with normal input → "
                        + "LAUNCH speculative copy (environmental, helps)");
            } else {
                // Data straggler: oversized input → speculation wastes resources.
                log.warning(() -> "Task " + t.getTaskId() + " straggler with " + t.getInputMb()
                        + "MB vs median " + medianInput + "MB → SKEW; speculation wastes a slot, use skew toolkit");
            }
        }
    }

    private long median(long[] sorted) {
        if (sorted.length == 0) return 0;
        return sorted[sorted.length / 2];
    }
}
