package com.bank.spark;

import com.bank.spark.model.TaskStat;
import com.bank.spark.service.SpeculationAdvisor;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: environmental straggler vs skew straggler decisions.
public class SpeculationDemo {

    private static final Logger log = Logger.getLogger(SpeculationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // multiplier 1.5, skew if input > 3x median input.
        SpeculationAdvisor advisor = new SpeculationAdvisor(1.5, 3.0);

        // Stage A: task 2 is slow but has NORMAL input (slow node) → speculation helps.
        List<TaskStat> stageA = List.of(
            new TaskStat(0, 1000, 100), new TaskStat(1, 1050, 100),
            new TaskStat(2, 4000, 105), new TaskStat(3, 980, 95));

        // Stage B: task 1 is slow AND has 10x input (skew) → speculation wastes a slot.
        List<TaskStat> stageB = List.of(
            new TaskStat(0, 900, 100), new TaskStat(1, 9000, 1000),
            new TaskStat(2, 950, 100), new TaskStat(3, 910, 100));

        log.info("=== Stage A (environmental straggler) ===");
        advisor.evaluate(stageA);
        log.info("=== Stage B (skew straggler) ===");
        advisor.evaluate(stageB);
        log.info("Speculation demo complete.");
    }
}
